import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.DeW-aKVm.js";const g=JSON.parse('{"title":"postgres-mcp-go","description":"A read-only Model Context Protocol server for PostgreSQL, written in Go, with 70+ tools for schema, data, performance, security, and migration analysis.","frontmatter":{"title":"postgres-mcp-go","description":"A read-only Model Context Protocol server for PostgreSQL, written in Go, with 70+ tools for schema, data, performance, security, and migration analysis.","section":"postgres-mcp-go","docType":"overview","outline":"deep"},"headers":[],"relativePath":"docs/postgres-mcp-go/index.md","filePath":"docs/postgres-mcp-go/index.md"}'),n={name:"docs/postgres-mcp-go/index.md"};function o(r,s,l,p,c,d){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="postgres-mcp-go" tabindex="-1">postgres-mcp-go <a class="header-anchor" href="#postgres-mcp-go" aria-label="Permalink to &quot;postgres-mcp-go&quot;">​</a></h1><p><code>postgres-mcp-go</code> is a <strong>read-only</strong> <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> (MCP) server for PostgreSQL, written in Go. It gives AI assistants safe, structured access to your databases for schema exploration, data profiling, query analysis, migration planning, and more.</p><h2 id="why-read-only" tabindex="-1">Why read-only <a class="header-anchor" href="#why-read-only" aria-label="Permalink to &quot;Why read-only&quot;">​</a></h2><p>Every query is validated before execution. <code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>, <code>DROP</code>, <code>ALTER</code>, <code>CREATE</code>, <code>TRUNCATE</code>, and other mutating statements are rejected before they reach the database. Stored procedures and functions are analyzed statically and never executed.</p><p>That makes the server safe to hand to an assistant that needs to understand a production database without being able to change it.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Read-only by design</strong> — mutating SQL is blocked by a validator.</li><li><strong>70+ tools</strong> covering schema discovery, data profiling, performance analysis, security auditing, migration assessment, and monitoring.</li><li><strong>Connection pooling</strong> with configurable limits and automatic cleanup.</li><li><strong>Stdio transport</strong> for Claude Desktop, Cline, and other MCP clients.</li><li><strong>Single binary</strong> for Linux, macOS, and Windows, plus a multi-arch container image.</li></ul><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><p>Set the connection with environment variables (they always override the config file), then run the server:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> POSTGRES_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">localhost</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> POSTGRES_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> POSTGRES_USER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">readonly_user</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> POSTGRES_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">secret</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> POSTGRES_DB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mydb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">postgres-mcp-go</span></span></code></pre></div><p>The server starts on stdio by default and waits for an MCP client to connect. See <a href="./configuration">Configuration</a> for <code>config.yaml</code> and client setup, and <a href="./tools">Tools</a> for the full tool list.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>postgres-mcp-go/</span></span>
<span class="line"><span>  cmd/server/            Entry point</span></span>
<span class="line"><span>  internal/</span></span>
<span class="line"><span>    adapters/mcp/        MCP protocol, tool registration</span></span>
<span class="line"><span>    postgres/            Service layer (queries, analysis)</span></span>
<span class="line"><span>    db/                  Connection pool, query execution</span></span>
<span class="line"><span>    infrastructure/      Config, logging</span></span>
<span class="line"><span>  pkg/version/           Build version info</span></span></code></pre></div><p>The server registers all tools with the MCP SDK and forwards tool calls to the PostgreSQL service layer. Every statement passes through the read-only validator first.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./installation">Installation</a></li><li><a href="./configuration">Configuration</a></li><li><a href="./tools">Tools</a></li></ul>`,16)])])}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
